create extension if not exists pgcrypto;
create schema if not exists app_private;
create table if not exists public.settings(key text primary key,value jsonb not null default '{}'::jsonb);
alter table public.settings enable row level security;
create table if not exists public.families(id uuid primary key default gen_random_uuid(),name text not null,sort_order int default 0,meeting_day text,meeting_time text,meeting_url text,notes text,created_at timestamptz default now());
alter table public.families enable row level security;
create table if not exists public.students(id uuid primary key default gen_random_uuid(),name text not null,phone text,email text,family_id uuid references public.families(id),stage text default 'candidate',university text,college text,study_level text,neighborhood text,marital_status text,under_twenty boolean default false,guardian_name text,guardian_phone text,led_before boolean default false,created_at timestamptz default now());
alter table public.students enable row level security;
create table if not exists public.accounts(user_id uuid primary key references auth.users(id) on delete cascade,email text,name text not null,phone text,role text not null default 'pending',title text,student_id uuid unique references public.students(id),created_at timestamptz default now());
alter table public.accounts enable row level security;
create table if not exists public.weeks(id uuid primary key default gen_random_uuid(),code text unique not null,sort_order int not null,kind text not null,title text not null,starts_on date not null,ends_on date not null,reflection text,lesson text,hadith text,tilawa text,riyad text,task_self text,task_home text,task_community text,discussion text,activity text,team_work text,deliverable text);
alter table public.weeks enable row level security;
create table if not exists public.events(id uuid primary key default gen_random_uuid(),kind text not null,title text not null,starts_at timestamptz,duration_minutes int,week_id uuid references public.weeks(id),family_id uuid references public.families(id),place text,notes text);
alter table public.events enable row level security;
create table if not exists public.roles_family(id uuid primary key default gen_random_uuid(),family_id uuid references public.families(id),student_id uuid references public.students(id),task text not null,cycle int not null,unique(family_id,task,cycle),unique(family_id,student_id,cycle));
alter table public.roles_family enable row level security;
create table if not exists public.rota_leader(id uuid primary key default gen_random_uuid(),family_id uuid references public.families(id),week_id uuid references public.weeks(id),student_id uuid references public.students(id),unique(family_id,week_id));
alter table public.rota_leader enable row level security;
create table if not exists public.minutes(id uuid primary key default gen_random_uuid(),family_id uuid references public.families(id),week_id uuid references public.weeks(id),meeting_date date,leader_id uuid references public.students(id),attendance_count int,summary text,decisions text,author_id uuid references auth.users(id),created_at timestamptz default now());
alter table public.minutes enable row level security;
create table if not exists public.docs_family(id uuid primary key default gen_random_uuid(),family_id uuid references public.families(id),kind text not null,body text,updated_at timestamptz default now(),unique(family_id,kind));
alter table public.docs_family enable row level security;
create table if not exists public.followups(id uuid primary key default gen_random_uuid(),student_id uuid references public.students(id),week_id uuid references public.weeks(id),majlis text,family_meeting text,wird_days int check(wird_days between 0 and 7),triple_task text,transferred_lesson text,rotating_task text,note text,recorded_by uuid references auth.users(id),updated_at timestamptz default now(),unique(student_id,week_id));
alter table public.followups enable row level security;
create table if not exists public.reports_self(id uuid primary key default gen_random_uuid(),student_id uuid references public.students(id),week_id uuid references public.weeks(id),wird_days int check(wird_days between 0 and 7),task_self text,task_home text,task_community text,note_self text,note_home text,note_community text,transferred_lesson text,transferred_to text,thought_read boolean default false,updated_at timestamptz default now(),unique(student_id,week_id));
alter table public.reports_self enable row level security;
create table if not exists public.cards(id uuid primary key default gen_random_uuid(),student_id uuid references public.students(id),aspect text not null,stage text not null,level int check(level between 0 and 3),note text,evaluator_id uuid references auth.users(id),updated_at timestamptz default now(),unique(student_id,aspect,stage));
alter table public.cards enable row level security;
create table if not exists public.goals(id uuid primary key default gen_random_uuid(),student_id uuid references public.students(id),aspect text not null,goal text not null,measure text,done boolean default false);
alter table public.goals enable row level security;
create table if not exists public.milestones(id uuid primary key default gen_random_uuid(),student_id uuid references public.students(id),code text not null,done boolean default false,done_at timestamptz,note text,unique(student_id,code));
alter table public.milestones enable row level security;
create table if not exists public.observations(id uuid primary key default gen_random_uuid(),student_id uuid references public.students(id),kind text not null,note text not null,secret boolean default false,week_id uuid references public.weeks(id),author_id uuid references auth.users(id),created_at timestamptz default now());
alter table public.observations enable row level security;
create table if not exists public.tasks(id uuid primary key default gen_random_uuid(),week_id uuid references public.weeks(id),section text not null,sort_order int default 0,body text not null,owner text,result text,due_on date,done boolean default false,done_at timestamptz,note text);
alter table public.tasks enable row level security;
create table if not exists public.journal(id uuid primary key default gen_random_uuid(),week_id uuid references public.weeks(id),success text,obstacle text,decision text,author_id uuid references auth.users(id));
alter table public.journal enable row level security;
create table if not exists public.questions(id uuid primary key default gen_random_uuid(),student_id uuid references public.students(id),kind text not null,body text not null,answer text,published boolean default false,status text default 'open',answered_at timestamptz,created_at timestamptz default now());
alter table public.questions enable row level security;
create table if not exists public.announcements(id uuid primary key default gen_random_uuid(),title text not null,body text not null,family_id uuid references public.families(id),pinned boolean default false,author_id uuid references auth.users(id),created_at timestamptz default now());
alter table public.announcements enable row level security;
create table if not exists public.resources(id uuid primary key default gen_random_uuid(),title text not null,url text not null,kind text not null,week_id uuid references public.weeks(id),note text,sort_order int default 0);
alter table public.resources enable row level security;
create table if not exists public.responses_survey(id uuid primary key default gen_random_uuid(),round text not null,answers jsonb not null,created_at timestamptz default now());
alter table public.responses_survey enable row level security;
create table if not exists public.done_survey(student_id uuid references public.students(id),round text not null,primary key(student_id,round));
alter table public.done_survey enable row level security;

create or replace function app_private.my_role() returns text language sql stable security definer set search_path='' as $$ select coalesce((select role from public.accounts where user_id=auth.uid()),'pending') $$;
create or replace function app_private.my_student() returns uuid language sql stable security definer set search_path='' as $$ select student_id from public.accounts where user_id=auth.uid() $$;
create or replace function app_private.my_family() returns uuid language sql stable security definer set search_path='' as $$ select family_id from public.students where id=app_private.my_student() $$;
create or replace function app_private.team() returns boolean language sql stable security definer set search_path='' as $$ select app_private.my_role() in ('admin','murafiqa','musaida') $$;
create or replace function app_private.lead() returns boolean language sql stable security definer set search_path='' as $$ select app_private.my_role() in ('admin','murafiqa') $$;
create or replace function app_private.coordinator(f uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.roles_family where family_id=f and student_id=app_private.my_student() and task='munassiqa' and cycle=coalesce((select (value#>>'{}')::int from public.settings where key='current_cycle'),1)) $$;
create or replace function app_private.same_family(s uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.students where id=s and family_id=app_private.my_family()) $$;
revoke all on schema app_private from public,anon;
grant usage on schema app_private to authenticated;
revoke all on all functions in schema app_private from public,anon;
grant execute on all functions in schema app_private to authenticated;
create or replace function app_private.signup() returns trigger language plpgsql security definer set search_path='' as $$
begin
 perform pg_advisory_xact_lock(291104);
 insert into public.accounts(user_id,email,name,phone,role)
 values(new.id,new.email,coalesce(nullif(new.raw_user_meta_data->>'full_name',''),split_part(new.email,'@',1)),new.raw_user_meta_data->>'phone',
 case when not exists(select 1 from public.accounts where role='admin') then 'admin' else 'pending' end);
 return new;
end $$;
drop trigger if exists algharisat_signup on auth.users;
create trigger algharisat_signup after insert on auth.users for each row execute function app_private.signup();
create or replace function app_private.account_guard() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if tg_op='UPDATE' and old.role='admin' and app_private.my_role()<>'admin' then raise exception 'لا يحق تعديل الإدارة';end if;
 if tg_op='UPDATE' and new.role='admin' and old.role is distinct from new.role and app_private.my_role()<>'admin' then raise exception 'لا يحق منح الإدارة';end if;
 return new;
end $$;
drop trigger if exists account_guard on public.accounts;
create trigger account_guard before update on public.accounts for each row execute function app_private.account_guard();
create policy settings_read on public.settings for select to authenticated using (app_private.team() or app_private.my_role()='gharisa');
create policy settings_write on public.settings for all to authenticated using (app_private.team()) with check (app_private.team());
create policy families_read on public.families for select to authenticated using (app_private.team() or id=app_private.my_family());
create policy families_write on public.families for all to authenticated using (app_private.team()) with check (app_private.team());
create policy students_read on public.students for select to authenticated using (app_private.team() or id=app_private.my_student() or (family_id is not null and family_id=app_private.my_family()));
create policy students_add on public.students for insert to authenticated with check (app_private.team());
create policy students_edit on public.students for update to authenticated using (app_private.team()) with check (app_private.team());
create policy students_delete on public.students for delete to authenticated using (app_private.lead());
create policy accounts_read on public.accounts for select to authenticated using (app_private.lead() or user_id=auth.uid());
create policy accounts_edit on public.accounts for update to authenticated using (app_private.lead()) with check (app_private.lead());
create policy weeks_read on public.weeks for select to authenticated using (app_private.team() or (app_private.my_role()='gharisa' and kind<>'prep'));
create policy weeks_write on public.weeks for all to authenticated using (app_private.team()) with check (app_private.team());
create policy events_read on public.events for select to authenticated using (app_private.team() or (app_private.my_role()='gharisa' and (family_id is null or family_id=app_private.my_family())));
create policy events_write on public.events for all to authenticated using (app_private.team()) with check (app_private.team());
create policy roles_family_read on public.roles_family for select to authenticated using (app_private.team() or family_id=app_private.my_family());
create policy roles_family_write on public.roles_family for all to authenticated using (app_private.team()) with check (app_private.team());
create policy rota_leader_read on public.rota_leader for select to authenticated using (app_private.team() or family_id=app_private.my_family());
create policy rota_leader_write on public.rota_leader for all to authenticated using (app_private.team()) with check (app_private.team());
create policy minutes_read on public.minutes for select to authenticated using (app_private.team() or family_id=app_private.my_family());
create policy minutes_write on public.minutes for all to authenticated using (app_private.team() or family_id=app_private.my_family()) with check (app_private.team() or family_id=app_private.my_family());
create policy docs_family_read on public.docs_family for select to authenticated using (app_private.team() or family_id=app_private.my_family());
create policy docs_family_write on public.docs_family for all to authenticated using (app_private.team() or family_id=app_private.my_family()) with check (app_private.team() or family_id=app_private.my_family());
create policy followups_read on public.followups for select to authenticated using (app_private.team() or student_id=app_private.my_student() or (app_private.same_family(student_id) and app_private.coordinator(app_private.my_family())));
create policy followups_write on public.followups for all to authenticated using (app_private.team() or (app_private.same_family(student_id) and app_private.coordinator(app_private.my_family()))) with check (app_private.team() or (app_private.same_family(student_id) and app_private.coordinator(app_private.my_family())));
create policy reports_self_read on public.reports_self for select to authenticated using (app_private.team() or student_id=app_private.my_student() or (app_private.same_family(student_id) and app_private.coordinator(app_private.my_family())));
create policy reports_self_add on public.reports_self for insert to authenticated with check (app_private.team() or student_id=app_private.my_student());
create policy reports_self_edit on public.reports_self for update to authenticated using (app_private.team() or student_id=app_private.my_student()) with check (app_private.team() or student_id=app_private.my_student());
create policy cards_read on public.cards for select to authenticated using (app_private.team() or student_id=app_private.my_student());
create policy cards_add on public.cards for insert to authenticated with check (app_private.team() or (student_id=app_private.my_student() and stage='self'));
create policy cards_edit on public.cards for update to authenticated using (app_private.team() or (student_id=app_private.my_student() and stage='self')) with check (app_private.team() or (student_id=app_private.my_student() and stage='self'));
create policy goals_read on public.goals for select to authenticated using (app_private.team() or student_id=app_private.my_student());
create policy goals_write on public.goals for all to authenticated using (app_private.team()) with check (app_private.team());
create policy milestones_read on public.milestones for select to authenticated using (app_private.team() or student_id=app_private.my_student());
create policy milestones_write on public.milestones for all to authenticated using (app_private.team()) with check (app_private.team());
create policy observations_read on public.observations for select to authenticated using (app_private.my_role()='murafiqa' or (app_private.team() and not secret and kind<>'حدود الستر'));
create policy observations_write on public.observations for all to authenticated using (app_private.my_role()='murafiqa' or (app_private.team() and not secret and kind<>'حدود الستر')) with check (app_private.my_role()='murafiqa' or (app_private.team() and not secret and kind<>'حدود الستر'));
create policy tasks_read on public.tasks for select to authenticated using (app_private.team());
create policy tasks_write on public.tasks for all to authenticated using (app_private.team()) with check (app_private.team());
create policy journal_read on public.journal for select to authenticated using (app_private.team());
create policy journal_write on public.journal for all to authenticated using (app_private.team()) with check (app_private.team());
create policy questions_read on public.questions for select to authenticated using (app_private.team() or student_id=app_private.my_student() or (published and status='answered'));
create policy questions_add on public.questions for insert to authenticated with check (app_private.team() or (student_id=app_private.my_student() and answer is null and not published and status='open'));
create policy questions_edit on public.questions for update to authenticated using(app_private.team()) with check(app_private.team());
create policy questions_delete on public.questions for delete to authenticated using(app_private.team() or (student_id=app_private.my_student() and status='open'));
create policy announcements_read on public.announcements for select to authenticated using (app_private.team() or (app_private.my_role()='gharisa' and (family_id is null or family_id=app_private.my_family())));
create policy announcements_write on public.announcements for all to authenticated using (app_private.team()) with check (app_private.team());
create policy resources_read on public.resources for select to authenticated using (app_private.team() or app_private.my_role()='gharisa');
create policy resources_write on public.resources for all to authenticated using (app_private.team()) with check (app_private.team());
create policy responses_survey_read on public.responses_survey for select to authenticated using (app_private.lead());
create policy done_survey_read on public.done_survey for select to authenticated using (app_private.lead() or student_id=app_private.my_student());

create or replace function public.submit_survey(p_answers jsonb,p_round text default 'p1') returns void language plpgsql security definer set search_path='' as $$
declare sid uuid;
begin
 sid:=app_private.my_student();
 if sid is null or app_private.my_role()<>'gharisa' then raise exception 'غير مصرح';end if;
 if not exists(select 1 from public.settings where key='survey_open' and value='true'::jsonb) then raise exception 'الاستبانة مغلقة';end if;
 if p_round<>'p1' or jsonb_typeof(p_answers)<>'array' or jsonb_array_length(p_answers)<>5 then raise exception 'إجابة غير صالحة';end if;
 insert into public.done_survey(student_id,round) values(sid,p_round);
 insert into public.responses_survey(round,answers) values(p_round,p_answers);
end $$;
revoke all on function public.submit_survey(jsonb,text) from public,anon;
grant execute on function public.submit_survey(jsonb,text) to authenticated;
grant select,insert,update,delete on all tables in schema public to authenticated;
insert into public.settings(key,value) values ('current_cycle','1'),('survey_open','false'),('program_name','"الغارسات"'),('stage_name','"المرحلة الأولى"'),('welcome','"أهلاً بك في رحلة الغارسات"'),('backup_phone','""') on conflict(key) do nothing;
